nextflow_process {

    name "Test Process HAMRONIZATION_RGI"
    script "../main.nf"
    process "HAMRONIZATION_RGI"

    tag "modules"
    tag "modules_nfcore"
    tag "hamronization"
    tag "hamronization/rgi"
    tag "rgi/main"
    tag "rgi/cardannotation"

    test("hamronization/rgi - haemophilus_influenzae - genome - fna.gz") {
        def card
        setup {
            card = extract('https://card.mcmaster.ca/latest/data', compression: 'tar.bz2')
            run("RGI_CARDANNOTATION") {
                script "../../../rgi/cardannotation/main.nf"
                process {
                    """
                    input[0] = file('${card}')
                    """
                }
            }

            run("RGI_MAIN") {
                script "../../../rgi/main/main.nf"
                process {
                    """
                    input[0] = [
                        [ id:'test' ],
                        file(params.modules_testdata_base_path + 'genomics/prokaryotes/haemophilus_influenzae/genome/genome.fna.gz', checkIfExists: true)
                    ]
                    input[1] = RGI_CARDANNOTATION.out.db
                    input[2] = []
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = RGI_MAIN.out.tsv
                input[1] = 'tsv'
                input[2] = '1.0.2'
                input[3] = '3.2.3'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }

    test("hamronization/rgi - haemophilus_influenzae - genome - fna.gz - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [ id:'test' ], [] ]
                input[1] = 'tsv'
                input[2] = '1.0.2'
                input[3] = '3.2.3'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

